    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bytes32 _batcherHash) public {
        bytes32 before = c.batcherHash(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.setL1BlockValues(0, 0, 0, bytes32(0), 0, _batcherHash, 0, 0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted && c.batcherHash() == before);
    }
    receive() external payable {}
}

