pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(bytes32 _batcherHash) internal {
        bytes32 before;
        try c.batcherHash() returns (bytes32 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, _batcherHash, 0, 0) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.batcherHash() == before);
    }

    function testFuzz_run(bytes32 _batcherHash) public {
        _run(_batcherHash);
    }

    receive() external payable {}
}
